CREATE TYPE public.app_role AS ENUM ('customer','provider','admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK (char_length(display_name)<=100), phone text CHECK (phone ~ '^\+27[0-9]{9}$'), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE FUNCTION public.create_account_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'customer'); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.create_account_profile() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER service_requesta_account_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_account_profile();
CREATE TABLE public.consents (user_id uuid PRIMARY KEY, privacy_version text NOT NULL CHECK(privacy_version='pilot-privacy-v1'), accepted_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.consents TO authenticated; GRANT ALL ON public.consents TO service_role;
ALTER TABLE public.consents ENABLE ROW LEVEL SECURITY;
CREATE POLICY consent_read ON public.consents FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_consent() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.consents WHERE user_id=auth.uid() AND privacy_version='pilot-privacy-v1') $$;
REVOKE ALL ON FUNCTION public.has_consent() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_consent() TO authenticated,service_role;
CREATE TABLE public.feature_flags (name text PRIMARY KEY CHECK(name IN ('public_bookings','electronic_payments','production_email','commission_enforcement','legal_approval')), enabled boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.feature_flags TO authenticated; GRANT ALL ON public.feature_flags TO service_role;
ALTER TABLE public.feature_flags ENABLE ROW LEVEL SECURITY;
CREATE POLICY flags_read ON public.feature_flags FOR SELECT TO authenticated USING(true);
CREATE TABLE public.audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, action text NOT NULL, entity_id uuid, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_events TO authenticated; GRANT ALL ON public.audit_events TO service_role;
ALTER TABLE public.audit_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_read ON public.audit_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.accept_pilot_privacy(p_name text,p_phone text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF char_length(trim(p_name)) NOT BETWEEN 1 AND 100 OR (p_phone IS NOT NULL AND p_phone !~ '^\+27[0-9]{9}$') THEN RAISE EXCEPTION 'Invalid profile'; END IF; UPDATE public.profiles SET display_name=trim(p_name),phone=p_phone WHERE id=auth.uid(); INSERT INTO public.consents(user_id,privacy_version) VALUES(auth.uid(),'pilot-privacy-v1') ON CONFLICT DO NOTHING; INSERT INTO public.audit_events(actor_id,action,entity_id) VALUES(auth.uid(),'privacy_accepted',auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.accept_pilot_privacy(text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.accept_pilot_privacy(text,text) TO authenticated;
CREATE TABLE public.service_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL, category text NOT NULL CHECK(category IN ('plumbing','electrical','motor_mechanics')), title text NOT NULL CHECK(char_length(trim(title)) BETWEEN 5 AND 120), description text NOT NULL CHECK(char_length(trim(description)) BETWEEN 20 AND 2000), area text NOT NULL CHECK(char_length(trim(area)) BETWEEN 2 AND 100), municipality text NOT NULL DEFAULT 'Buffalo City Metropolitan Municipality' CHECK(municipality='Buffalo City Metropolitan Municipality'), city text NOT NULL DEFAULT 'East London' CHECK(city='East London'), timing text NOT NULL CHECK(timing IN ('flexible','this_week','as_soon_as_possible')), status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','accepted','quoted','approved','in_progress','awaiting_completion','completed','disputed','cancelled')), is_demo boolean NOT NULL DEFAULT true, idempotency_key uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(customer_id,idempotency_key));
GRANT SELECT ON public.service_requests TO authenticated; GRANT ALL ON public.service_requests TO service_role;
ALTER TABLE public.service_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY customer_requests ON public.service_requests FOR SELECT TO authenticated USING(customer_id=auth.uid() AND public.has_consent());
CREATE INDEX requests_customer_created ON public.service_requests(customer_id,created_at DESC);
CREATE TABLE public.provider_profiles (user_id uuid PRIMARY KEY, category text NOT NULL CHECK(category IN ('plumbing','electrical','motor_mechanics')), area text NOT NULL, identity_status text NOT NULL DEFAULT 'not_checked' CHECK(identity_status IN ('not_checked','pending','checked')), trade_status text NOT NULL DEFAULT 'not_checked' CHECK(trade_status IN ('not_checked','pending','reviewed')));
GRANT SELECT ON public.provider_profiles TO authenticated; GRANT ALL ON public.provider_profiles TO service_role;
ALTER TABLE public.provider_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY provider_own ON public.provider_profiles FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.has_consent());
CREATE TABLE public.request_responses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.service_requests(id), provider_id uuid NOT NULL, decision text NOT NULL CHECK(decision IN ('accepted','declined')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(request_id,provider_id));
GRANT SELECT ON public.request_responses TO authenticated; GRANT ALL ON public.request_responses TO service_role;
ALTER TABLE public.request_responses ENABLE ROW LEVEL SECURITY;
CREATE POLICY responses_read ON public.request_responses FOR SELECT TO authenticated USING(public.has_consent() AND (provider_id=auth.uid() OR EXISTS(SELECT 1 FROM public.service_requests r WHERE r.id=request_id AND r.customer_id=auth.uid())));
CREATE FUNCTION public.provider_can_see_open(p_request_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'provider') AND public.has_consent() AND EXISTS(SELECT 1 FROM public.service_requests r JOIN public.provider_profiles p ON p.user_id=auth.uid() AND p.category=r.category WHERE r.id=p_request_id AND NOT r.is_demo AND (r.status='submitted' OR EXISTS(SELECT 1 FROM public.request_responses rr WHERE rr.request_id=r.id AND rr.provider_id=auth.uid() AND rr.decision='accepted'))) $$;
REVOKE ALL ON FUNCTION public.provider_can_see_open(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.provider_can_see_open(uuid) TO authenticated;
CREATE POLICY provider_requests ON public.service_requests FOR SELECT TO authenticated USING(public.provider_can_see_open(id));
CREATE TABLE public.request_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.service_requests(id), actor_id uuid NOT NULL, status text NOT NULL, note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.request_events TO authenticated; GRANT ALL ON public.request_events TO service_role;
ALTER TABLE public.request_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY events_read ON public.request_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.service_requests r WHERE r.id=request_id));
CREATE FUNCTION public.create_service_request(p_category text,p_title text,p_description text,p_area text,p_timing text,p_key uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'customer') OR NOT public.has_consent() THEN RAISE EXCEPTION 'Customer privacy consent required'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0)); SELECT id INTO v_id FROM public.service_requests WHERE customer_id=auth.uid() AND idempotency_key=p_key; IF v_id IS NOT NULL THEN RETURN v_id; END IF; IF (SELECT count(*) FROM public.service_requests WHERE customer_id=auth.uid() AND created_at>now()-interval '1 hour')>=5 THEN RAISE EXCEPTION 'Limit of 5 requests per hour reached'; END IF; INSERT INTO public.service_requests(customer_id,category,title,description,area,timing,idempotency_key,is_demo) VALUES(auth.uid(),p_category,trim(p_title),trim(p_description),trim(p_area),p_timing,p_key,true) RETURNING id INTO v_id; INSERT INTO public.request_events(request_id,actor_id,status,note) VALUES(v_id,auth.uid(),'submitted','Demonstration request saved. Not sent to providers.'); INSERT INTO public.audit_events(actor_id,action,entity_id) VALUES(auth.uid(),'demo_request_created',v_id); RETURN v_id; END $$;
REVOKE ALL ON FUNCTION public.create_service_request(text,text,text,text,text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_service_request(text,text,text,text,text,uuid) TO authenticated;
CREATE FUNCTION public.cancel_service_request(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_consent() THEN RAISE EXCEPTION 'Consent required'; END IF; UPDATE public.service_requests SET status='cancelled',updated_at=now() WHERE id=p_id AND customer_id=auth.uid() AND status='submitted'; IF NOT FOUND THEN RAISE EXCEPTION 'Request cannot be cancelled'; END IF; INSERT INTO public.request_events(request_id,actor_id,status,note) VALUES(p_id,auth.uid(),'cancelled','Cancelled by customer.'); INSERT INTO public.audit_events(actor_id,action,entity_id) VALUES(auth.uid(),'request_cancelled',p_id); END $$;
REVOKE ALL ON FUNCTION public.cancel_service_request(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.cancel_service_request(uuid) TO authenticated;
CREATE TABLE public.quotes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.service_requests(id), provider_id uuid NOT NULL, scope text NOT NULL CHECK(char_length(scope) BETWEEN 20 AND 3000), labour_cents bigint NOT NULL CHECK(labour_cents>=0), callout_cents bigint NOT NULL CHECK(callout_cents>=0), parts_cents bigint NOT NULL CHECK(parts_cents>=0), total_cents bigint GENERATED ALWAYS AS (labour_cents+callout_cents+parts_cents) STORED, assumptions text NOT NULL, timing text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.quotes TO authenticated; GRANT ALL ON public.quotes TO service_role;
ALTER TABLE public.quotes ENABLE ROW LEVEL SECURITY;
CREATE POLICY quotes_read ON public.quotes FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.service_requests r WHERE r.id=request_id));
CREATE TABLE public.approved_quotes (request_id uuid PRIMARY KEY REFERENCES public.service_requests(id), quote_id uuid NOT NULL REFERENCES public.quotes(id), customer_id uuid NOT NULL, snapshot jsonb NOT NULL, approved_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.approved_quotes TO authenticated; GRANT ALL ON public.approved_quotes TO service_role;
ALTER TABLE public.approved_quotes ENABLE ROW LEVEL SECURITY;
CREATE POLICY approved_read ON public.approved_quotes FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.service_requests r WHERE r.id=request_id));
CREATE FUNCTION public.reject_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Immutable record'; END $$;
CREATE TRIGGER approved_immutable BEFORE UPDATE OR DELETE ON public.approved_quotes FOR EACH ROW EXECUTE FUNCTION public.reject_mutation();
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON public.audit_events FOR EACH ROW EXECUTE FUNCTION public.reject_mutation();
CREATE TRIGGER events_immutable BEFORE UPDATE OR DELETE ON public.request_events FOR EACH ROW EXECUTE FUNCTION public.reject_mutation();
CREATE TABLE public.completion_confirmations (request_id uuid NOT NULL REFERENCES public.service_requests(id), user_id uuid NOT NULL, confirmed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(request_id,user_id));
GRANT SELECT ON public.completion_confirmations TO authenticated; GRANT ALL ON public.completion_confirmations TO service_role;
ALTER TABLE public.completion_confirmations ENABLE ROW LEVEL SECURITY;
CREATE POLICY completion_read ON public.completion_confirmations FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.service_requests r WHERE r.id=request_id));
CREATE TABLE public.support_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid REFERENCES public.service_requests(id), opened_by uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('false_profile','workmanship','safety','payment','completion','commission','cancellation','fraud','privacy')), description text NOT NULL CHECK(char_length(description) BETWEEN 20 AND 3000), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.support_cases TO authenticated; GRANT ALL ON public.support_cases TO service_role;
ALTER TABLE public.support_cases ENABLE ROW LEVEL SECURITY;
CREATE POLICY cases_read ON public.support_cases FOR SELECT TO authenticated USING(public.has_consent() AND (opened_by=auth.uid() OR public.has_role(auth.uid(),'admin')));
CREATE TABLE public.commission_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rate_bps integer NOT NULL DEFAULT 1500 CHECK(rate_bps BETWEEN 0 AND 10000), base_definition text, legal_approved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.commission_versions TO authenticated; GRANT ALL ON public.commission_versions TO service_role;
ALTER TABLE public.commission_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY versions_read ON public.commission_versions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.calculate_commission(p_base bigint,p_bps integer) RETURNS bigint LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ BEGIN IF p_base<0 OR p_bps NOT BETWEEN 0 AND 10000 THEN RAISE EXCEPTION 'Invalid money'; END IF; RETURN round(p_base::numeric*p_bps/10000)::bigint; END $$;
CREATE TABLE public.commission_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.service_requests(id), provider_id uuid NOT NULL, version_id uuid NOT NULL REFERENCES public.commission_versions(id), base_cents bigint NOT NULL CHECK(base_cents>=0), fee_cents bigint NOT NULL CHECK(fee_cents>=0), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.commission_ledger TO authenticated; GRANT ALL ON public.commission_ledger TO service_role;
ALTER TABLE public.commission_ledger ENABLE ROW LEVEL SECURITY;
CREATE POLICY ledger_read ON public.commission_ledger FOR SELECT TO authenticated USING(public.has_consent() AND (provider_id=auth.uid() OR public.has_role(auth.uid(),'admin')));
CREATE TRIGGER ledger_immutable BEFORE UPDATE OR DELETE ON public.commission_ledger FOR EACH ROW EXECUTE FUNCTION public.reject_mutation();
CREATE TABLE public.fee_notices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ledger_id uuid NOT NULL REFERENCES public.commission_ledger(id), notice_at timestamptz NOT NULL DEFAULT now(), due_at timestamptz NOT NULL, disputed boolean NOT NULL DEFAULT false, final_notice_at timestamptz);
GRANT SELECT ON public.fee_notices TO authenticated; GRANT ALL ON public.fee_notices TO service_role;
ALTER TABLE public.fee_notices ENABLE ROW LEVEL SECURITY;
CREATE POLICY notices_read ON public.fee_notices FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.commission_ledger l WHERE l.id=ledger_id));
CREATE TABLE public.identity_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, storage_path text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.identity_documents TO authenticated; GRANT ALL ON public.identity_documents TO service_role;
ALTER TABLE public.identity_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY documents_read ON public.identity_documents FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.has_consent());
CREATE FUNCTION public.guard_request_transition() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.customer_id<>OLD.customer_id OR NEW.is_demo<>OLD.is_demo THEN RAISE EXCEPTION 'Ownership and demonstration mode cannot change'; END IF; IF NEW.status=OLD.status THEN RETURN NEW; END IF; IF NEW.is_demo AND NEW.status<>'cancelled' THEN RAISE EXCEPTION 'Demo requests cannot become real jobs'; END IF; IF NOT ((OLD.status='submitted' AND NEW.status IN ('accepted','cancelled')) OR (OLD.status='accepted' AND NEW.status IN ('quoted','cancelled','disputed')) OR (OLD.status='quoted' AND NEW.status IN ('approved','cancelled','disputed')) OR (OLD.status='approved' AND NEW.status IN ('in_progress','disputed')) OR (OLD.status='in_progress' AND NEW.status IN ('awaiting_completion','disputed')) OR (OLD.status='awaiting_completion' AND NEW.status IN ('completed','disputed'))) THEN RAISE EXCEPTION 'Invalid job transition'; END IF; IF NEW.status IN ('approved','in_progress','awaiting_completion','completed') AND NOT EXISTS(SELECT 1 FROM public.approved_quotes WHERE request_id=NEW.id) THEN RAISE EXCEPTION 'Approved quote required'; END IF; IF NEW.status='completed' AND (NOT EXISTS(SELECT 1 FROM public.completion_confirmations WHERE request_id=NEW.id AND user_id=NEW.customer_id) OR NOT EXISTS(SELECT 1 FROM public.completion_confirmations c JOIN public.approved_quotes a ON a.request_id=c.request_id JOIN public.quotes q ON q.id=a.quote_id WHERE c.request_id=NEW.id AND c.user_id=q.provider_id)) THEN RAISE EXCEPTION 'Both parties must confirm completion'; END IF; RETURN NEW; END $$;
CREATE TRIGGER request_transition BEFORE UPDATE ON public.service_requests FOR EACH ROW EXECUTE FUNCTION public.guard_request_transition();
CREATE FUNCTION public.guard_ledger() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.service_requests WHERE id=NEW.request_id AND status='completed' AND NOT is_demo) THEN RAISE EXCEPTION 'Only genuine completed jobs can incur commission'; END IF; IF NOT EXISTS(SELECT 1 FROM public.commission_versions WHERE id=NEW.version_id AND legal_approved AND base_definition IS NOT NULL AND public.calculate_commission(NEW.base_cents,rate_bps)=NEW.fee_cents) THEN RAISE EXCEPTION 'Approved commission version required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER ledger_guard BEFORE INSERT ON public.commission_ledger FOR EACH ROW EXECUTE FUNCTION public.guard_ledger();
CREATE FUNCTION public.guard_fee_notice() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.due_at<>((NEW.notice_at AT TIME ZONE 'Africa/Johannesburg')+interval '7 days') AT TIME ZONE 'Africa/Johannesburg' THEN RAISE EXCEPTION 'Due date must be seven calendar days after notice'; END IF; RETURN NEW; END $$;
CREATE TRIGGER notice_guard BEFORE INSERT OR UPDATE ON public.fee_notices FOR EACH ROW EXECUTE FUNCTION public.guard_fee_notice();